import { test, expect } from '@playwright/test';

test.describe('Out-of-Stock Message on Add to Cart', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/products');
  });

  test('should display out-of-stock message when adding unavailable item to cart', async ({ page }) => {
    // Verify product page loads
    const productCard = page.getByRole('region', { name: /product/i });
    await expect(productCard).toBeVisible();

    // Verify product details are visible
    const productName = page.getByText(/product name/i);
    await expect(productName).toBeVisible();

    // Verify add to cart button is visible
    const addToCartButton = page.getByRole('button', { name: /add to cart/i });
    await expect(addToCartButton).toBeVisible();

    // Click add to cart button for unavailable item
    await addToCartButton.click();

    // Verify out-of-stock message appears
    const outOfStockMessage = page.getByText(/item is out of stock/i);
    await expect(outOfStockMessage).toBeVisible();

    // Verify cart icon is still visible
    const cartIcon = page.getByRole('img', { name: /cart/i });
    await expect(cartIcon).toBeVisible();

    // Verify cart count is updated to 0
    const cartCount = page.getByText(/cart is empty/i);
    await expect(cartCount).toBeVisible();

    // Verify product card is still visible
    await expect(productCard).toBeVisible();
  });

  test('should not display out-of-stock message when item is available', async ({ page }) => {
    // Verify product page loads
    const productCard = page.getByRole('region', { name: /product/i });
    await expect(productCard).toBeVisible();

    // Verify product details are visible
    const productName = page.getByText(/product name/i);
    await expect(productName).toBeVisible();

    // Verify add to cart button is visible
    const addToCartButton = page.getByRole('button', { name: /add to cart/i });
    await expect(addToCartButton).toBeVisible();

    // Click add to cart button for available item
    await addToCartButton.click();

    // Verify out-of-stock message does not appear
    const outOfStockMessage = page.getByText(/item is out of stock/i);
    await expect(outOfStockMessage).not.toBeVisible();

    // Verify cart icon is visible
    const cartIcon = page.getByRole('img', { name: /cart/i });
    await expect(cartIcon).toBeVisible();

    // Verify cart count is updated
    const cartCount = page.getByText(/cart is empty/i);
    await expect(cartCount).not.toBeVisible();

    // Verify product card is still visible
    await expect(productCard).toBeVisible();
  });
});
